window.VO = [{"id":"n01","text":"Read this in your mother's voice.","at":0.24,"t0":0.12,"t1":1.775},{"id":"n02","text":"You heard her, didn't you? And I wrote that in English. How many of you heard English?","at":6.15,"t0":3.075,"t1":7.53},{"id":"n03","text":"I've got four of these, and one won't work.","at":15.86,"t0":7.93,"t1":10.085},{"id":"n04","text":"Now she's walked in.","at":20.97,"t0":10.485,"t1":11.7},{"id":"n05","text":"You just fixed your posture, didn't you?","at":25.9,"t0":12.95,"t1":14.82},{"id":"n06","text":"Now you've embarrassed her in front of guests.","at":30.48,"t0":15.24,"t1":17.27},{"id":"n07","text":"You pay rent, and that still goes straight to your stomach.","at":37.64,"t0":18.82,"t1":21.555},{"id":"n08","text":"Last one.","at":44.11,"t0":22.055,"t1":22.89},{"id":"n09","text":"Strange, isn't it? Like someone doing an impression of her.","at":50.38,"t0":25.19,"t1":28.46},{"id":"n10","text":"Your brain built that voice out of everything she's ever said to you.","at":57.76,"t0":28.88,"t1":32.35},{"id":"n11","text":"So how many times has she actually said that one?","at":65.3,"t0":32.65,"t1":35.465},{"id":"n12","text":"And how many times has she said this?","at":72.53,"t0":36.265,"t1":38.255},{"id":"n13","text":"It's the same sentence.","at":80.01,"t0":40.005,"t1":41.315},{"id":"n14","text":"For some of you, this is the only way left to hear her.","at":84.33,"t0":42.165,"t1":45.125},{"id":"n15","text":"The rest of you still have the original.","at":91.45,"t0":45.725,"t1":47.81},{"id":"n16","text":"Have you got one recording of her asking?","at":96.22,"t0":48.11,"t1":50.215}];
